    ('BEV-OLATTE-PEACH-20', 'olatte-peach', 'OKF Olatte Peach — Carton (20)', 'OKF Olatte Peach', 'Carton (20)', 20, 13800, 690, 'OKF', null, 'Beverages', '240ml', null, null, null, 'A peach latte that layers stone fruit over a milky base without turning heavy.', 'A peach latte that layers stone fruit over a milky base without turning heavy.', 'A peach latte that layers stone fruit over a milky base without turning heavy. Sweet but not cloying, and unusual enough to be worth trying if you have only ever had peach as an iced tea. Sold in the slim 240ml can.', 'Good chilled, and equally good warmed in cold weather.', 'Water, sugar, skimmed milk powder, peach juice concentrate, vegetable cream, natural flavours, emulsifier, stabiliser.', 'Contains milk.', '{}'::jsonb, 'https://kfoods.lk/images/products/okf-olatte-peach.jpeg', 'assets/products/olatte-peach.jpeg', 'https://kfoods.lk/products/olatte-peach.html', 63, true),
    ('BEV-OLATTE-STRAWBERRY-1', 'olatte-strawberry', 'OKF Olatte Strawberry — Single Can', 'OKF Olatte Strawberry', 'Single Can', 1, 690, 690, 'OKF', null, 'Beverages', '240ml', null, null, 'New', 'A strawberry latte with the fruit up front and a soft milky finish behind it.', 'A strawberry latte with the fruit up front and a soft milky finish behind it.', 'The strawberry version of the Olatte can, and the easiest one to hand to someone who has never tried a Korean milk drink. Strawberry sits up front, sweet and jammy rather than sharp, with the milky base filling in underneath so it drinks smooth instead of thin. Sold in the same slim 240ml can as the peach.', 'Best cold, straight from the chiller. Shake the can before opening.', 'Water, sugar, skimmed milk powder, strawberry juice concentrate, vegetable cream, natural flavours, emulsifier, stabiliser, colour.', 'Contains milk.', '{}'::jsonb, 'https://kfoods.lk/images/products/okf-olatte-strawberry.jpeg', 'assets/products/olatte-strawberry.jpeg', 'https://kfoods.lk/products/olatte-strawberry.html', 64, true),
