-- ---------------------------------------------------------------------------
-- 3. FAQs — so answers on WhatsApp match answers on the website.
-- ---------------------------------------------------------------------------
insert into faqs (business_id, question, answer, sort_order)
select b.id, v.question, v.answer, v.sort_order
from businesses b
cross join (values
    ('Where does K FOOD deliver?', 'Everywhere in Sri Lanka — Colombo, Kandy, Galle, Kurunegala, Gampaha, Malabe, Kegalle, Matara, Anuradhapura, Jaffna and all 25 districts. Courier is a flat LKR 400 island-wide and free on orders over LKR 5,000. Most orders arrive in 2–4 days.', 1),
    ('Is there a minimum order?', 'No minimum — order as much or as little as you like, from a single pack or one drink to a full carton. Delivery is flat LKR 400 island-wide and free over LKR 5,000.', 2),
    ('How do I pay?', 'After the order is sent on WhatsApp, K FOOD confirms the total, then payment is made by bank transfer to Hatton National Bank (HNB), Alawwa branch, account name Kumarasinghe H G B N, account number 123020163895. Send the receipt on WhatsApp and the order is dispatched. There is no online card payment at this stage.', 3),
    ('What if something arrives damaged?', 'Message K FOOD on WhatsApp within 7 days of delivery. If an item is damaged, expired or wrong, K FOOD collects it at their cost and sends a replacement or a full refund. Unopened items in original condition can be returned in the same window; opened food packs can''t be returned, for food-safety reasons.', 4),
    ('Are these the real Korean products?', 'Yes — genuine Nongshim, Migawon, Binggrae and OKF products imported from South Korea. Every product page lists the pack''s ingredients and allergens.', 5),
    ('What is the Shin Ramyun price in Sri Lanka at K FOOD?', 'Shin Ramyun Original 120g is LKR 650 per pack, LKR 3,250 for a 5 Pack and LKR 13,000 for a 20-pack carton at kfoods.lk. Most Korean ramen packs here are LKR 650–895, and every product page lists the best price for singles, 5 Packs and cartons.', 6),
    ('Is kfoods.lk an online-only store?', 'Yes — kfoods.lk is an online Korean food store for Sri Lanka. Orders are placed on the website, confirmed on WhatsApp (077 295 3107), and couriered island-wide.', 7),
    ('Does K FOOD deliver Korean ramen island-wide in Sri Lanka?', 'Yes. K FOOD (kfoods.lk) delivers Korean ramyeon and drinks to every district in Sri Lanka. Delivery is a flat LKR 400 island-wide and free for orders over LKR 5,000. Orders arrive in 2–4 days.', 8),
    ('What is K FOOD''s return policy?', 'If an item arrives damaged, expired or is not what was ordered, tell K FOOD on WhatsApp within 7 days of delivery. They collect it at their cost and send a replacement or a full refund. Unopened items in original condition can be returned within the same 7 days; opened food packs cannot be returned for food-safety reasons.', 9)
) as v(question, answer, sort_order)
where b.name = 'K FOOD'
on conflict (business_id, question) do update set
  answer = excluded.answer,
  sort_order = excluded.sort_order;
